-- 034: добірка ігор, квестів, тем клубів і фільмів для «Банку ідей» (можна запускати повторно)
INSERT OR IGNORE INTO club_ideas (id, team_id, cat, text, descr, author_id, author, created) VALUES
('bank_g01', '_bank', 'game', 'Вгору, вниз, бум', 'По 3–4 людини складають кулаки один на одного так, щоб дві руки одного гравця не були поруч. Ведучий командує:
• «Вгору» — нижній кулак переміщається нагору
• «Вниз» — верхній кулак переміщається вниз
• «Бум» — верхній кулак має вдарити по наступному, а той має швидко прибрати руку
Якщо верхній гравець влучив — наступний вибуває, якщо ні — вибуває той, хто бив.', '', 'Young Life', '2026-11-27T15:00:01.000Z'),
('bank_g02', '_bank', 'game', 'Кульки на нозі', 'Кожному гравцю привʼязують повітряну кульку до ноги. Завдання — наступити на чужу кульку й лопнути її, захищаючи свою. Перемагає той, у кого залишилась ціла кулька.', '', 'Young Life', '2026-11-27T15:00:02.000Z'),
('bank_g03', '_bank', 'game', 'Корова жива — мертва — спить', 'Ведучий озвучує команди:
• «Корова жива» — учасники встають у позу корови
• «Корова спить» — лягають на бік
• «Корова мертва» — лягають на спину й піднімають руки й ноги догори
Хто зробив неправильно або останнім — вибуває.', '', 'Young Life', '2026-11-27T15:00:03.000Z'),
('bank_g04', '_bank', 'game', 'Принц, принцеса і дракон', 'Грається як «Камінь-ножиці-папір»:
• принцеса перемагає принца
• принц перемагає дракона
• дракон перемагає принцесу
За сигналом усі одночасно показують вибір жестом. Команда, що виграла, отримує бал.', '', 'Young Life', '2026-11-27T15:00:04.000Z'),
('bank_g05', '_bank', 'game', 'Земля — море', 'Стрибок уперед — «земля», стрибок назад — «море». Ведучий швидко каже команди, учасники мають стрибати в правильний бік. Хто помилився або запізнився — вибуває.', '', 'Young Life', '2026-11-27T15:00:05.000Z'),
('bank_g06', '_bank', 'game', 'Пташка на дроті', 'Грають у парах. Ведучий називає частини тіла, які треба зʼєднати: «рука до ноги», «спина до спини» тощо. Коли ведучий каже «Пташка на дроті», один гравець стає на одне коліно, а інший сідає йому на коліно. Хто останній — вибуває.', '', 'Young Life', '2026-11-27T15:00:06.000Z'),
('bank_g07', '_bank', 'game', 'Молекули', 'Ведучий називає число (наприклад, «5»). Учасники мають швидко обʼєднатися в групи по стільки людей. Хто залишився зайвим — вибуває.', '', 'Young Life', '2026-11-27T15:00:07.000Z'),
('bank_g08', '_bank', 'game', 'Стакан на голові', 'Кожному ставлять паперовий стакан на голову. Завдання — збити стакани з інших гравців і не впустити свій. Хто втратив стакан — вибуває.', '', 'Young Life', '2026-11-27T15:00:08.000Z'),
('bank_g09', '_bank', 'game', 'Правда — брехня', 'Ведучий зачитує твердження. У залі дві стіни: праворуч «Правда», ліворуч «Брехня». Гравці швидко біжать до тієї, що відповідає їхньому вибору. Хто вибрав неправильно — вибуває.', '', 'Young Life', '2026-11-27T15:00:09.000Z'),
('bank_g10', '_bank', 'game', 'Хто перший викладе сторіс на тему', 'Ведучий оголошує завдання, наприклад: «фото з ложкою на голові». Гравці мають швидко зняти й викласти сторіс у соцмережі та відмітити клуб. Хто зробив першим — виграв.', '', 'Young Life', '2026-11-27T15:00:10.000Z'),
('bank_g11', '_bank', 'game', 'Кахут', 'Вікторина в Kahoot!: гравці відповідають на питання зі своїх телефонів, бали за правильність і швидкість.', '', 'Young Life', '2026-11-27T15:00:11.000Z'),
('bank_g12', '_bank', 'game', 'Схопити стаканчик', 'Учасники стають спина до спини, між ними на підлозі стаканчик. Ведучий дає різні команди, куди тримати руки («голова», «коліна» тощо). На слово «Стаканчик» треба схопити стаканчик. Хто взяв — виграв.', '', 'Young Life', '2026-11-27T15:00:12.000Z'),
('bank_g13', '_bank', 'game', 'Всередину — назовні (In — out)', '', '', 'Young Life', '2026-11-27T15:00:13.000Z'),
('bank_g14', '_bank', 'game', 'Камінь — ножиці — папір проти проектора', 'На проекторі вмикається відео, де лідер показує камінь, ножиці чи папір. Учасники грають проти екрана. Хто програв — вибуває (однаковий жест = перемога). Перемагає той, хто залишиться останнім.', '', 'Young Life', '2026-11-27T15:00:14.000Z'),
('bank_g15', '_bank', 'game', 'Вежа зі спагеті й маршмелоу', 'Командам треба побудувати найвищу вежу за 10 хвилин. Виграє команда з найвищою стійкою вежею.', '', 'Young Life', '2026-11-27T15:00:15.000Z'),
('bank_g16', '_bank', 'game', 'Вежа з повітряних кульок і скотчу', 'Побудувати найвищу вежу за 10–15 хвилин. Правило: не можна кріпити конструкцію до стін, стелі чи меблів — лише до підлоги. Виграє команда з найвищою вежею.', '', 'Young Life', '2026-11-27T15:00:16.000Z'),
('bank_g17', '_bank', 'game', 'Вежа з Lego за завданнями', 'Команда будує вежу з Lego. Кожен гравець отримує картку з особистим завданням (або уточненням до вежі). Усі мовчать і не показують свою картку іншим.
Картки:
1. Ви можете розмовляти
2. Тільки ви можете будувати вежу
3. Вежа складається з 10 поверхів
4. Кожен парний поверх має бути синього кольору
5. Кожен непарний поверх має бути червоного кольору
6. На 5 поверсі має бути 5 блоків
7. Останній поверх має бути жовтим
8. Вежа має складатися із 40 блоків
9. На останньому поверсі має бути 1 блок
10. На першому поверсі має бути 10 блоків', '', 'Young Life', '2026-11-27T15:00:17.000Z'),
('bank_g18', '_bank', 'game', 'Що це?', 'На екрані показують маленьку частину обʼєкта. Гравці відгадують, що це.', '', 'Young Life', '2026-11-27T15:00:18.000Z'),
('bank_g19', '_bank', 'game', 'Скільки пальців?', 'Гра в парах. Учасники ховають одну руку за спину й на рахунок «три» показують пальцями число. Хто першим правильно назве суму — виграє.', '', 'Young Life', '2026-11-27T15:00:19.000Z'),
('bank_g20', '_bank', 'game', 'Пів-пів-пів', 'Двоє гравців одночасно кажуть «пів-пів-пів…», поки не закінчиться повітря. Хто протримався довше — виграє.', '', 'Young Life', '2026-11-27T15:00:20.000Z'),
('bank_g21', '_bank', 'game', 'Дуель', 'Усі стають у коло. Ведучий називає імʼя когось із учасників. Ця людина присідає, а двоє сусідів збоку мають швидко навести пальці один на одного й сказати «Пів!». Хто запізнився або помилився — вибуває.', '', 'Young Life', '2026-11-27T15:00:21.000Z'),
('bank_g22', '_bank', 'game', 'Коробка піци', 'У кожного гравця в руці коробка піци. Завдання — вибити коробку з рук суперника, захищаючи свою. Хто залишився з коробкою — переміг.', '', 'Young Life', '2026-11-27T15:00:22.000Z'),
('bank_g23', '_bank', 'game', 'Не дивись, куди вказує палець', 'На рахунок «три» один гравець показує пальцем в одну з чотирьох сторін, а інший дивиться в одну зі сторін. Хто подивився туди ж, куди вказує палець, — вибуває.', '', 'Young Life', '2026-11-27T15:00:23.000Z'),
('bank_g24', '_bank', 'game', 'Вгадати пісню за 5 секунд', 'Ведучий вмикає перші 5 секунд пісні. Хто першим вгадає — отримує бал.', '', 'Young Life', '2026-11-27T15:00:24.000Z'),
('bank_g25', '_bank', 'game', 'Вгадай пісню через Google Translate', 'Ведучий читає текст пісні, перекладений через Google Translate англійською. Гравці мають відгадати оригінал.', '', 'Young Life', '2026-11-27T15:00:25.000Z'),
('bank_g26', '_bank', 'game', '100 до 1 (як брейн-ринг)', 'Ведучий ставить підготовлені питання: усі відповіді правильні, а гравцям треба вгадати найпопулярнішу. Наприклад, що лежить на столі бухгалтера?
1. Калькулятор
2. Документи
3. Ручка
4. Гроші', '', 'Young Life', '2026-11-27T15:00:26.000Z'),
('bank_g27', '_bank', 'game', 'Передати стаканчик паличками для чаю', 'Гравці стають у два ряди (дві команди), кожен тримає паличку для чаю в зубах. Завдання команди — передати стаканчик по ряду лише паличками.', '', 'Young Life', '2026-11-27T15:00:27.000Z'),
('bank_g28', '_bank', 'game', 'Салат', 'Гравці сідають у коло, кожен отримує номер. Ведучий із зав’язаними очима стоїть у центрі з порожньою пластиковою пляшкою. Коли ведучий називає два номери, ці люди міняються місцями, а ведучий намагається торкнутися їх пляшкою, поки вони не сядуть.', '', 'Young Life', '2026-11-27T15:00:28.000Z'),
('bank_g29', '_bank', 'game', 'Гра в PowerPoint', 'Готова інтерактивна гра в презентації PowerPoint — можна купити, є багато християнських ресурсів.', '', 'Young Life', '2026-11-27T15:00:29.000Z'),
('bank_g30', '_bank', 'game', 'Гра на знайомство', 'Кожен отримує лист із питаннями («хто має собаку», «хто був за кордоном» тощо). Треба якнайшвидше знайти в залі людей, які підходять під опис, і вписати їхні імена. Хто перший заповнив — виграв.', '', 'Young Life', '2026-11-27T15:00:30.000Z'),
('bank_g31', '_bank', 'game', 'Сніжки', 'Дві команди стають по різні боки лінії. На рахунок «три» всі кидають на чужий бік шкарпетки, згорнуті кулькою. Через 30 секунд рахують, у кого на полі більше шкарпеток, — та команда програла.', '', 'Young Life', '2026-11-27T15:00:31.000Z'),
('bank_g32', '_bank', 'game', '4 фото — 1 слово', 'Ведучий робить колаж із 4 асоціацій, гравці мають вгадати, про кого йдеться (відома людина, член команди тощо).', '', 'Young Life', '2026-11-27T15:00:32.000Z'),
('bank_g33', '_bank', 'game', 'Взуття за лінію', 'Учасники стають за стартовою лінією. Завдання — покласти (не кинути) своє взуття якомога далі. Виграє той, чиє взуття опиниться найдалі від лінії. Можна використовувати допомогу команди й підручні речі. Заборонено торкатися підлоги за лінією.', '', 'Young Life', '2026-11-27T15:00:33.000Z'),
('bank_g34', '_bank', 'game', 'Стаканчики на мотузках', 'На паперовий стаканчик надягають резинку для волосся (або канцелярську), до неї привʼязують 4 мотузки. Усі учасники беруться за мотузки й разом керують резинкою, щоб піднімати стаканчики й побудувати з них піраміду.', '', 'Young Life', '2026-11-27T15:00:34.000Z'),
('bank_g35', '_bank', 'game', 'Тенісна кулька у стакан', 'Матеріали: тенісна кулька, будівельні кутики (пластикові чи металеві), стакан. Учасники мають, використовуючи лише 3–4 кутики, перенести кульку на кілька метрів і покласти її у стакан. Команда постійно міняється місцями. Перемагає команда, яка зробить це найшвидше.', '', 'Young Life', '2026-11-27T15:00:35.000Z'),
('bank_q01', '_bank', 'quest', 'Зелена пʼятка', 'В одного з лідерів пʼятка на одній нозі пофарбована в зелений. Усі лідери одягають дуже багато шкарпеток (по 5 на ногу). Гра по станціях: команди обирають лідера, виконують його завдання й знімають 1 шкарпетку (обирають ліву чи праву). Команди можуть приходити до тих самих лідерів кілька разів (не підряд), поки не знайдуть зелену пʼятку.', '', 'Young Life', '2026-11-27T15:01:01.000Z'),
('bank_q02', '_bank', 'quest', 'Веселка', 'Учасники проходять 7 станцій із завданнями. Після кожної станції ведучий малює на руці лінію кольоровим маркером. Лідери бігають з мочалками й змивають лінії. Завдання — зібрати повну веселку з 7 кольорів.', '', 'Young Life', '2026-11-27T15:01:02.000Z'),
('bank_q03', '_bank', 'quest', 'Полювання на сміття', 'Складіть список предметів, які команди мають знайти в місті й сфотографувати як доказ.', '', 'Young Life', '2026-11-27T15:01:03.000Z'),
('bank_q04', '_bank', 'quest', 'Геокешинг', 'Сховайте предмети або підказки по місту й дайте командам GPS-координати, щоб їх знайти. Можна використовувати QR-коди з координатами й завданнями.', '', 'Young Life', '2026-11-27T15:01:04.000Z'),
('bank_q05', '_bank', 'quest', 'Алфавітне завдання', 'Команди мають сфотографувати обʼєкти в місті, що відповідають кожній літері алфавіту.', '', 'Young Life', '2026-11-27T15:01:05.000Z'),
('bank_g36', '_bank', 'ggame', 'Прищіпки на одяг', 'Кожен отримує 1–3 прищіпки для одягу. За 1 хвилину треба причепити їх на одяг іншим гравцям. Програє той, у кого найбільше прищіпок на одязі (можна додати покарання).', '', 'Young Life', '2026-11-27T15:02:01.000Z'),
('bank_g37', '_bank', 'ggame', 'Колесо фортуни', 'Протягом усього клубу працює колесо фортуни. Перемога в будь-якій грі лише зупиняє гру, а хто отримає приз — вирішує колесо фортуни. Найвезучіший завжди в плюсі (можна й покарання).', '', 'Young Life', '2026-11-27T15:02:02.000Z'),
('bank_g38', '_bank', 'ggame', 'Скітлз-лотерея', 'На початку клубу всі заповнюють бланк: скільки цукерок кожного кольору в упаковці Скітлз. Протягом клубу одна людина рахує (або є готове відео на YouTube). Хто був найближче — отримує пачку Скітлз (можна розіграти по кожному кольору окремо).', '', 'Young Life', '2026-11-27T15:02:03.000Z'),
('bank_g39', '_bank', 'ggame', 'Щасливчик', 'Одного з лідерів оголошено Щасливчиком (але невідомо, кого саме). У нього 50 грн, і він з радістю віддасть їх 11-й людині, яка потисне йому руку й скаже факт про себе. Добре працює на знайомство.', '', 'Young Life', '2026-11-27T15:02:04.000Z'),
('bank_g40', '_bank', 'ggame', 'Жива ялинка', 'Виграє команда, яка найкраще прикрасить одного з гравців новорічними іграшками.', '', 'Young Life', '2026-11-27T15:02:05.000Z'),
('bank_g41', '_bank', 'ggame', 'Хто за ковдрою', 'Дві команди ховаються за ковдрою й висувають наперед одного з гравців. На рахунок «три» ковдра опускається, і гравці мають якнайшвидше сказати імʼя суперника.', '', 'Young Life', '2026-11-27T15:02:06.000Z'),
('bank_g42', '_bank', 'ggame', 'Кантрі', 'Гра в парах: тримаючись за руки, треба наступити супернику на ногу. На фоні — весела музика (наприклад, кантрі).', '', 'Young Life', '2026-11-27T15:02:07.000Z'),
('bank_g43', '_bank', 'ggame', 'Надивленість', 'Треба вгадати мультфільм за одним стоп-кадром (головне — без головних героїв у кадрі).', '', 'Young Life', '2026-11-27T15:02:08.000Z'),
('bank_g44', '_bank', 'ggame', 'Шукачі', 'Заховайте в клубі кілька предметів (зазвичай стікери). Приз отримує кожен, хто знайде.', '', 'Young Life', '2026-11-27T15:02:09.000Z'),
('bank_g45', '_bank', 'ggame', 'Скрабл', 'Кожному на вході пишемо літеру на долоні. Завдання — скласти якнайбільше слів разом з іншими гравцями. Слова фотографують, щоб порахувати.', '', 'Young Life', '2026-11-27T15:02:10.000Z'),
('bank_g46', '_bank', 'ggame', 'Довгий язик', 'Дві команди стають у лінію, кожен гравець тримає ротом прищіпку для одягу так, щоб міг її відкривати й закривати. Завдання — якнайшвидше передати печиво «Марія» по лінії прищіпками.', '', 'Young Life', '2026-11-27T15:02:11.000Z'),
('bank_g47', '_bank', 'ggame', 'Бум', 'Усі гравці надувають повітряну кульку й кладуть під футболку (або привʼязують спереду). 2–3 лідери з голками мають лопнути всі кульки, гравці можуть ухилятися. Виграє той, хто залишиться з кулькою.', '', 'Young Life', '2026-11-27T15:02:12.000Z'),
('bank_g48', '_bank', 'ggame', 'Паперовий тімбілдинг', 'Кожен гравець має паперовий мʼяч. Спершу в парах: треба одночасно кинути мʼяч один одному й спіймати. Потім пари обʼєднуються в кола по чотири й одночасно кидають по колу. Потім — усі разом в одному колі.', '', 'Young Life', '2026-11-27T15:02:13.000Z'),
